// Pseudocode sketch: update loop for online ICA with dropout handling
while (streaming) {
  x = read4Channels();
  W = updateWhitening(x);
  A = chooseDemixer(W, x, dropoutMask);
  s = A * x;
  updatePermutation(s);
}
